void vm_init(VM* vm) {
    memset(vm->registers, 0, sizeof(vm->registers));
    memset(vm->memory, 0, sizeof(vm->memory));
    memset(vm->stack, 0, sizeof(vm->stack));
    vm->sp = -1;
    vm->ip = 0;
    vm->try_depth = 0;
    memset(&vm->flags, 0, sizeof(vm->flags));
    memset(&vm->last_error, 0, sizeof(vm->last_error));
}

